"""Register this agent with the LiteLLM gateway (generated by genproj).

The container is the source of truth for its own card: registration runs at
startup, is idempotent by name, and FAILS OPEN. A gateway outage must not stop
the agent from serving - the failure is logged and the server keeps running; the
next restart (or a periodic retry) re-registers.

The credential is a key bound to a `proxy_admin` USER, read from the environment
variable named by `registrationKeyEnv` (LITELLM_REGISTRATION_KEY). It is NOT the
master key, and it is NOT a key minted with `user_role` on `/key/generate` -
that field is silently ignored and yields a non-admin key that gets HTTP 403
from POST /v1/agents. See agent/README.md for how to mint the user and key.

WHY THE LOOKUP IS NOT JUST `GET /v1/agents`
-------------------------------------------
`GET /v1/agents` is a *view*, filtered by the calling key's owner: every row
carries `created_by`/`updated_by`, and the listing shows what that key owns - it
is not an authority on whether this agent is registered. A key bound to a
`proxy_admin` user (the credential this template deliberately uses) has a
narrower owner view than the master key, so the listing can omit a row that
exists. A row written by an older build can also carry no owner stamp and
disappear from the listing while remaining present, callable and addressable by
id.

Because the name lookup *is* that listing, a restarted agent that read itself as
absent would `POST` a name that was already taken, get a duplicate-name refusal,
and have no way back: its entry is there, working, and unreachable from here.
Every restart repeats it, and the log points at the gateway, which is the wrong
place to look.

So the lookup degrades. The listing is tried first; if it does not show this
agent, the id remembered from the last registration is checked directly with
`GET /v1/agents/{id}` - which is *not* filtered. The id is remembered at
`$AGENT_STATE_DIR/registry-agent-id` (default:
`~/.local/state/pydantic-agent/<agent-name>/registry-agent-id`), and remembering
it is best-effort: an unwritable or unconfigured path is logged and swallowed,
because a missing file costs the fallback, not a registration that otherwise
worked. The default path lives in the container's image layer, so it survives a
restart of the same container but not a rebuild/recreate (e.g. Watchtower
pulling a new image). To keep it across redeploys - the case the fallback exists
for - mount a writable host directory with `docker-container.dataMounts`
(`readOnly: false`, since dataMounts are read-only by default) and point
`AGENT_STATE_DIR` at it.

A `POST` refusal whose body says the name is taken is treated as proof the
entry exists: the entry is re-looked-up and rewritten in place with
`PUT /v1/agents/{id}`. The detection keys on the body string, not the status,
because the live proxy answers `500` with Prisma's
`Unique constraint failed on the fields: (agent_name)` while the documented
shape is a `400`. If the entry still cannot be found, the failure is reported
honestly and distinctly: the agent IS registered and addressable by id, but this
key cannot see or manage its own entry - a listing-filter problem, not a proxy
fault.
"""

from __future__ import annotations

import os
from pathlib import Path

import httpx

LITELLM_BASE_URL = os.environ.get("LITELLM_BASE_URL", "http://litellm:4000")
REGISTRATION_KEY_ENV = "LITELLM_REGISTRATION_KEY"
TIMEOUT = float(os.environ.get("LITELLM_REGISTRATION_TIMEOUT", "10"))

# Where the id LiteLLM assigned is remembered between runs. A runtime setting,
# not a generation-time one: the durable location is a property of the
# deployment's volumes, not of the repository. Empty means "use the default
# below".
STATE_DIR_ENV = "AGENT_STATE_DIR"
REMEMBERED_ID_FILENAME = "registry-agent-id"


async def register_with_litellm(
    *,
    agent_name: str,
    card_url: str,
    protocol_version: str,
    description: str,
    skills: list,
) -> None:
    """Create or update this agent's record in the gateway. Fail open."""
    key = os.environ.get(REGISTRATION_KEY_ENV, "")
    if not key:
        print(
            f"[register] {REGISTRATION_KEY_ENV} is not set - skipping LiteLLM "
            "registration (fail open). See agent/README.md.",
            flush=True,
        )
        return

    card = {
        "name": agent_name,
        "description": description,
        "url": card_url,
        # Pin the wire format LiteLLM serves for this agent. Unpinned, the
        # served version is inferred per client request while the proxied card
        # defaults to 1.0, so card and responses can disagree.
        "protocolVersion": protocol_version,
        "version": "0.1.0",
        "defaultInputModes": ["application/json"],
        "defaultOutputModes": ["application/json"],
        "capabilities": {"streaming": True},
        "skills": skills,
    }
    payload = {"agent_name": agent_name, "agent_card_params": card}
    headers = {
        "Authorization": f"Bearer {key}",
        "Content-Type": "application/json",
    }

    try:
        async with httpx.AsyncClient(timeout=TIMEOUT) as client:
            agent_id = await _find_agent_id(client, headers, agent_name)
            if agent_id is not None:
                response = await _update(client, headers, agent_id, payload)
                verb = "updated"
            else:
                response = await client.post(
                    f"{LITELLM_BASE_URL}/v1/agents", json=payload, headers=headers
                )
                if _is_duplicate_name(response):
                    # The name is taken although the listing did not show it.
                    # The name is this agent's identity, so the entry holding it
                    # is a previous instance of us: re-look it up and rewrite it
                    # in place rather than failing and repeating forever.
                    agent_id = await _find_agent_id(client, headers, agent_name)
                    if agent_id is None:
                        print(_name_taken_message(agent_name, response.text), flush=True)
                        return
                    print(
                        f"[register] the listing did not show '{agent_name}' but the "
                        f"name is taken; reclaiming the existing entry {agent_id}",
                        flush=True,
                    )
                    response = await _update(client, headers, agent_id, payload)
                    verb = "updated"
                else:
                    verb = "registered"
            response.raise_for_status()
            if agent_id is None:
                agent_id = _agent_id_from_response(response)
            _remember_agent_id(agent_name, agent_id)
            print(f"[register] {verb} '{agent_name}' with {LITELLM_BASE_URL}", flush=True)
    except Exception as exc:  # fail open: a gateway outage must not stop serving
        print(
            f"[register] could not register '{agent_name}' with "
            f"{LITELLM_BASE_URL}: {exc!r} (fail open; will retry on restart)",
            flush=True,
        )


async def _update(
    client: httpx.AsyncClient, headers: dict, agent_id: str, payload: dict
) -> httpx.Response:
    """Rewrite the existing entry in place (no delete/post window, no id churn)."""
    return await client.put(
        f"{LITELLM_BASE_URL}/v1/agents/{agent_id}", json=payload, headers=headers
    )


async def _find_agent_id(
    client: httpx.AsyncClient, headers: dict, agent_name: str
) -> str | None:
    """This agent's gateway id, or None when it is genuinely not registered.

    The name scan is the listing, and the listing is filtered by the calling
    key's owner - so it is not authoritative. When it comes up empty the id
    remembered from the last registration is checked directly with
    `GET /v1/agents/{id}`, which is not filtered. See the module docstring.
    """
    response = await client.get(f"{LITELLM_BASE_URL}/v1/agents", headers=headers)
    response.raise_for_status()
    found = _find_by_name(response, agent_name)
    if found is not None:
        return found
    return await _agent_id_by_remembered_id(client, headers, agent_name)


def _find_by_name(response: httpx.Response, agent_name: str) -> str | None:
    """The id listed under this agent's name, or None.

    A listing that is not an array (`{}`, an HTML error page) reads as "not
    listed": the caller's next move is the same either way, and a shape
    disagreement here must not be able to stop an agent registering.
    """
    try:
        listed = response.json()
    except ValueError:
        return None
    if not isinstance(listed, list):
        return None
    for agent in listed:
        if not isinstance(agent, dict):
            continue
        card = agent.get("agent_card_params") or {}
        if agent.get("agent_name") == agent_name or card.get("name") == agent_name:
            return agent.get("agent_id")
    return None


async def _agent_id_by_remembered_id(
    client: httpx.AsyncClient, headers: dict, agent_name: str
) -> str | None:
    """The remembered id, if the proxy still holds a row under it that is ours.

    Three answers, each with a different consequence: a row that is ours is
    taken, so the caller updates it in place; a row that is gone (404) means the
    caller creates; a row that is now someone else's name is not adopted, so the
    caller creates and the proxy refuses the name - reported honestly rather
    than silently adopting a row that is not ours.
    """
    remembered = _remembered_agent_id(agent_name)
    if not remembered:
        return None

    response = await client.get(
        f"{LITELLM_BASE_URL}/v1/agents/{remembered}", headers=headers
    )
    if response.status_code == 404:
        return None
    response.raise_for_status()

    try:
        row = response.json()
    except ValueError:
        row = None
    listed_name = row.get("agent_name") if isinstance(row, dict) else None
    if listed_name != agent_name:
        print(
            f"[register] the remembered id {remembered} now names "
            f"{listed_name!r}, not '{agent_name}'; not adopting it",
            flush=True,
        )
        return None

    # Loud on purpose: this is the path a filtered listing creates, and every
    # downstream symptom (a duplicate-name POST, an entry that cannot be
    # rewritten) is a consequence of it.
    print(
        f"[register] the LiteLLM agent listing does not show '{agent_name}', but "
        f"the by-id read does; resolving by remembered id {remembered}. The "
        "listing is filtered by the calling key's owner.",
        flush=True,
    )
    return remembered


def _remembered_id_path(agent_name: str) -> Path:
    """Where the remembered id lives: `$AGENT_STATE_DIR`, else a per-agent default."""
    configured = os.environ.get(STATE_DIR_ENV, "").strip()
    base = (
        Path(configured)
        if configured
        else Path.home() / ".local" / "state" / "pydantic-agent" / agent_name
    )
    return base / REMEMBERED_ID_FILENAME


def _remembered_agent_id(agent_name: str) -> str | None:
    """The id remembered from a previous registration, if any."""
    try:
        remembered = _remembered_id_path(agent_name).read_text(encoding="utf-8").strip()
    except Exception:
        return None
    return remembered or None


def _remember_agent_id(agent_name: str, agent_id: str | None) -> None:
    """Persist the id so a filtered listing cannot hide this agent next boot.

    Failure is logged and swallowed: an unwritable state path costs the by-id
    fallback after a restart, which is not a reason to fail a registration that
    otherwise succeeded. Written to a sibling and renamed, so a reader never
    sees a half-written id.
    """
    if not agent_id:
        return
    try:
        path = _remembered_id_path(agent_name)
        path.parent.mkdir(parents=True, exist_ok=True)
        temporary = path.with_name(path.name + ".writing")
        temporary.write_text(f"{agent_id}\n", encoding="utf-8")
        temporary.replace(path)
    except Exception as exc:
        print(
            f"[register] could not remember the agent id for '{agent_name}' "
            f"(the registration still succeeded): {exc!r}",
            flush=True,
        )


def _agent_id_from_response(response: httpx.Response) -> str | None:
    """The `agent_id` LiteLLM returned, when it returned one."""
    try:
        body = response.json()
    except ValueError:
        return None
    if not isinstance(body, dict):
        return None
    agent_id = body.get("agent_id")
    return agent_id if isinstance(agent_id, str) and agent_id else None


def _is_duplicate_name(response: httpx.Response) -> bool:
    """Does this refusal mean "that name is already taken"?

    Keyed on the body, not the status: the documented shape is a `400` with
    "already exists", but the live proxy answers `500` with Prisma's
    `Unique constraint failed on the fields: (agent_name)`. A status test would
    miss the case that actually happens, and a `500` is otherwise
    indistinguishable from a real server fault.
    """
    body = response.text or ""
    return "Unique constraint failed" in body or "already exists" in body


def _name_taken_message(agent_name: str, body: str) -> str:
    """The honest, distinct report for a name this key cannot resolve."""
    return (
        f"[register] LiteLLM refused to create '{agent_name}' because the name is "
        "already taken, and its agent listing does not show the entry that holds "
        "it, so the id cannot be read. This agent IS registered and addressable by "
        "id, but this key cannot see or manage its own entry: that is a "
        "listing-filter problem (GET /v1/agents shows what the calling key owns), "
        "not a proxy fault. Clear it from an admin key, or grant this key "
        f"visibility. Registration will retry on restart. Response body: {body}"
    )
